wrapCanvasText = (context, text, x, y, maxWidth, lineHeight, maxLines = 3) =&gt; {
  const words = text.split(/\s+/)
  const lines = []
  let line = ""
  for (const word of words) {
    const test = line ? `${line} ${word}` : word
    if (context.measureText(test).width &gt; maxWidth && line) {
      lines.push(line)
      line = word
    } else {
      line = test
    }
  }
